package verify;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.when;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

@SpringBootTest(classes = GreeterApp.class)
class GreeterTest {

    // Replaces the Greeter bean defined by GreeterApp with a Mockito mock.
    // (@MockBean was removed in Spring Boot 4; @MockitoBean is its replacement.)
    @MockitoBean
    private Greeter greeter;

    @Autowired
    private Greeter autowiredGreeter;

    @Test
    void autowiredGreeterIsTheMock() {
        when(greeter.greet()).thenReturn("mock");

        assertEquals("mock", autowiredGreeter.greet());
    }
}

